const lines = $input.item.json.lines;
let model = 0;

if (lines.includes('extrato mensal')) {
  model = 1;
}
if (lines.includes('Agência: Conta: Nome:')) {
  model = 2;
}
if (lines.includes('Logotipo Itaú')) {
  model = 3;
}

return { model, lines };

const bank = "ITAU";
const linhas = $input.item.json.lines;

const regex = /^(\d{2}\/\d{2})\s+(.+?)\s+([\d.]+,\d{2}-?)$/;
const regexSec = /^(.+?)\s+([\d.]+,\d{2}-?)$/;
const regexPercentual = /^\d+%$/;
const regexComposta = /\b\d{2}\/\d{2}\/\d{2}\b/;

const termosIgnorados = [
  "saldo anterior",
  "saldo final",
  "na conta corrente",
  "0,00",
  "saques efetuados",
  "compras a débito",
  "limite contratado",
  "limite variável",
  "imposto sobre operações financeiras",
  "cdi",
  "ibx",
  "ibovespa",
  "dolar comercial",
  "poupanca",
  "igp-m",
  "ibrx",
  "r$ ",
  "depósitos e recebimentos",
  "transferências, docs e teds",
  "outras entradas"
];

const clientName = linhas[5];

let dataAtual = "";

const deveIgnorarLinha = (descricao, valor) => {
  const descLower = descricao.toLowerCase();
  return (
    valor === "0,00" ||
    regexPercentual.test(descricao) ||
    termosIgnorados.some(termo => descLower.includes(termo))
  );
};

const transacoes = linhas.map(linha => {

  if (regexComposta.test(linha)) {
    return null;
  }

  const match = linha.match(regex);
  const matchSec = !match && dataAtual !== "" ? linha.match(regexSec) : null;

  if (!match && !matchSec) {
    return null;
  }

  const descricaoMatch = match ? match[2] : matchSec[1];
  const valorMatch = match ? match[3] : matchSec[2];

  if (deveIgnorarLinha(descricaoMatch, valorMatch)) {
    return null;
  }

  if (match) {
    dataAtual = match[1];
  }

  let today = new Date;

  return {
    data: dataAtual + '/' + today.getFullYear(),
    documento: "",
    descricao: descricaoMatch,
    valor: valorMatch.replace('-', ""),
    tipoTransacao: valorMatch.endsWith("-") ? "SAIDA" : "ENTRADA"
  };

}).filter(Boolean);

const count = transacoes.length;

return { bank, clientName, count, transacoes };

const bank = "ITAU";
const linhas = $input.item.json.lines;

const clientRegex =
  /^(\d{4})\s+(\d{5}-\d)\s+([A-Z\s]+)\s+([A-Z]+\/\d{4})\s+(\d{9})$/;

const ignorarDescricoes = new Set([
  "SALDO INICIAL",
  "SALDO APLIC AUT MAIS",
  "SALDO PARCIAL",
  "SALDO ANTERIOR",
  "SALDO FINAL"
]);

const transactionRegex =
  /^(\d{2}\/\d{2})\s+(.+?)(?:\s+(\d+))?\s+(\d{1,3}(?:\.\d{3})*,\d{2})(?:\s+(-))?(?:\s+.*)?$/;

const clientName = linhas[1].match(clientRegex)[3];

const transacoes = linhas
  .map(linha => {

    const match = linha.match(transactionRegex);

    if (!match) return null;

    const [
      ,
      dataTransacao,
      descricao,
      documento,
      valor,
      negativo
    ] = match;

    const descricaoLimpa = descricao.trim();

    // Ignora descrições que não são transações
    if (ignorarDescricoes.has(descricaoLimpa.toUpperCase())) {
      return null;
    }

    const today = new Date();

    return {
      data: dataTransacao + '/' + today.getFullYear(),
      ...(documento ? { documento } : {}),
      descricao: descricaoLimpa,
      valor,
      tipoTransacao: negativo ? "SAIDA" : "ENTRADA"
    };

  })
  .filter(Boolean);

const count = transacoes.length;

return {
  bank,
  clientName,
  count,
  transacoes
};

const bank = "ITAU";
const linhas = $input.item.json.lines;

const clientName = linhas[2].match(/^Nome:\s*(.+)$/)[1];
const transactionRegex = /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(-?\d+\.\d{2})$/;

const transacoes = linhas.map(linha => {

  const match = linha.match(transactionRegex);

  if (!match) return null;

  const [, dataTransacao, descricao, valor] = match;

  return {
    data: dataTransacao,
    documento: "",
    descricao: descricao,
    valor: valor.replace("-", "").replace(".", ","),
    tipoTransacao: valor.startsWith("-") ? "SAIDA" : "ENTRADA"
  };

}).filter(Boolean);

const count = transacoes.length;

return { bank, clientName, count, transacoes };
